import React from 'react';

import { showModal } from '@ui-kit/Modal';

import ShoppingEditModal from './components/ShoppingEditModal';
import { IShoppingItem } from './shopping.types';
import { IHikingData } from '../../@types/hiking.types';

export function editShoppingAsync(
  data: IShoppingItem,
  hikingData: IHikingData,
  user: { id: number; name: string; photo: string },
): Promise<IShoppingItem> {
  return new Promise((resolve) => {
    showModal({
      title: data.name,
      size: 'lg',
      children: (closeHandler: () => void) => (
        <ShoppingEditModal
          data={data}
          hikingData={hikingData}
          onSave={(updatedItem) => {
            resolve(updatedItem);
            closeHandler();
          }}
          onCancel={closeHandler}
          user={user}
        />
      ),
    });
  });
}

export default { editShoppingAsync };
