import React, { useContext } from 'react';

import ArrowRepeat from '@pohodnik/icons/svg/Arrows/ArrowRepeat';

import PageLoader from '@components/PageLoader';
import notificationHelper, { err, success } from '@helpers/notificationHelper';
import PohAlert from '@ui-kit/Alert';
import PohBadge, { BadgeVariant } from '@ui-kit/Badge/Badge';
import Breadcrumb from '@ui-kit/Breadcrumb';
import PohButton, { ButtonVariant } from '@ui-kit/Button';
import Empty from '@ui-kit/Empty';
import PohInput from '@ui-kit/Input';
import InputSizes from '@ui-kit/Input/InputSizes';
import InputTypes from '@ui-kit/Input/InputTypes';
import PohCol from '@ui-kit/layout/Col';
import PohContainer from '@ui-kit/layout/Container';
import PohRow from '@ui-kit/layout/Row';
import PohList from '@ui-kit/List';

import ShoppingListItem from './components/ShoppingListItem';
import { editShoppingAsync } from './helpers';
import { mapShoppingItemToBack, mapShoppingItemToFront } from './shopping.mappers';
import { editShoppingItem, getShoppingList, initShoppingItems } from './shopping.service';
import { IShoppingItem } from './shopping.types';
import style from './style.module.less';
import { AuthContext } from '../../../../contexts/AuthContext';
import { getHikingDataAsync } from '../../@services/hiking.service';
import { getHikingAccessGroupAsync } from '../../@services/hikingRules.service';
import { HikingAccessGroup } from '../../@types/hiking.rules';
import { IHikingData } from '../../@types/hiking.types';

interface IHikingShoppingProps {
  id_hiking: number;
}

const HikingShopping: React.FC<IHikingShoppingProps> = ({ id_hiking }) => {
  const [hikingData, setHikingData] = React.useState<IHikingData | null>(null);
  const [items, setItems] = React.useState<IShoppingItem[]>([]);
  const [actualityKey, setActualityKey] = React.useState(new Date());
  const [accessRule, setAccessRule] = React.useState<HikingAccessGroup | null>(null);
  const [q, setQ] = React.useState('');

  const [isBaseInfoLoading, setIsBaseInfoLoading] = React.useState(true);
  const [isListLoading, setIsListLoading] = React.useState(false);

  const authContext = useContext(AuthContext);

  const user = {
    id: +authContext.user!.id,
    name: [authContext.user!.name, authContext.user!.surname].join(' '),
    photo: authContext.user!.photo || authContext.user!.photo,
  };

  React.useEffect(() => {
    const init = async () => {
      try {
        setIsBaseInfoLoading(true);
        await getHikingDataAsync(id_hiking).then(setHikingData);
        await getHikingAccessGroupAsync(id_hiking).then(setAccessRule);
      } finally {
        setIsBaseInfoLoading(false);
      }
    };

    init().catch(err);
  }, [id_hiking]);

  React.useEffect(() => {
    if (!hikingData) {
      return;
    }

    const load = async () => {
      try {
        setIsListLoading(true);
        await getShoppingList(id_hiking).then((itemsDTO) => {
          const mappedItems = itemsDTO.map(mapShoppingItemToFront(hikingData.hikers));
          setItems(mappedItems);
          success('Обновлено');
        });
      } finally {
        setIsListLoading(false);
      }
    };

    load().catch(err);
  }, [hikingData, actualityKey]);

  const handleEdit = (item: IShoppingItem) => {
    if (!hikingData) {
      throw new Error('No hiking data');
    }

    if (!hikingData.hikers.find((x) => x.idUser === authContext.user?.id)) {
      return notificationHelper.warn('Нет доступа');
    }

    editShoppingAsync(item, hikingData, user).then((patch) => {
      editShoppingItem(mapShoppingItemToBack(patch)).then(() => {
        success('Сохранено');
        setItems((its) => its.map((i) => (i.id === item.id ? { ...i, ...patch } : i)));
      });
    });
  };

  if (isBaseInfoLoading) {
    return <PageLoader />;
  }
  if (!hikingData) {
    return <PohAlert>No hikingData</PohAlert>;
  }

  return (
    <PohContainer>
      <Breadcrumb
        data={[
          { href: '/hiking', text: 'Походы' },
          { href: `/hiking/${id_hiking}`, text: hikingData.name ?? '' },
          { href: `/hiking/${id_hiking}/shopping`, text: 'Закупки', active: true },
        ]}
      />
      <div className="d-flex justify-content-between mb-3 align-items-center">
        <h3 className="d-none d-sm-block">Закупки для похода «{hikingData.name}»</h3>
        <div className="d-sm-none">
          <small className="text-muted d-block mb-n1">{hikingData.name}</small>
          <b>Список покупок</b>
        </div>
        <div>
          {accessRule &&
            [HikingAccessGroup.Boss, HikingAccessGroup.All, HikingAccessGroup.Full].includes(
              accessRule,
            ) && (
              <PohButton
                variant={ButtonVariant.Light}
                onClick={() => {
                  window.prompt('activation code 1-4') === '1234' &&
                    initShoppingItems(id_hiking)
                      .then(() => {
                        success('done');
                        location.reload();
                      })
                      .catch(err);
                }}
              >
                Generate
              </PohButton>
            )}
          <PohBadge variant={BadgeVariant.Success}>
            Куплено: {items.filter((x) => x.isComplete).length} из {items.length}
          </PohBadge>
        </div>
      </div>

      <PohRow>
        <PohCol sm={12}>
          {isListLoading && <PageLoader />}
          {!isListLoading && items?.length === 0 && <Empty>Нет списка покупок</Empty>}
          {!isListLoading && actualityKey && (
            <small className="text-muted">
              Актуально на {new Date(actualityKey).toLocaleTimeString()}
            </small>
          )}
          {!isListLoading && items?.length > 0 && (
            <PohInput
              className="my-1"
              size={InputSizes.Small}
              prefix={'BB'}
              type={InputTypes.search}
              placeholder="Поиск"
              onChange={setQ}
              value={q}
            />
          )}
          {!isListLoading && items?.length > 0 && (
            <PohList
              data={items
                .filter(
                  (i) =>
                    !q.length ||
                    [i.name, i.comment, i.usages.map((x) => x.name).join('*')]
                      .join('|')
                      .toLowerCase()
                      .includes(q.toLowerCase()),
                )
                .sort((a, b) =>
                  a.isComplete < b.isComplete ? -1 : Number(a.isComplete > b.isComplete),
                )
                .map((item) => ({
                  key: item.id,
                  onClick: () => handleEdit(item),
                  action: true,
                  content: <ShoppingListItem data={item} />,
                }))}
            />
          )}
        </PohCol>
      </PohRow>
      <PohButton
        className={style.floatingBtn}
        variant={ButtonVariant.Primary}
        icon={true}
        onClick={() => setActualityKey(new Date())}
      >
        <ArrowRepeat />
      </PohButton>
    </PohContainer>
  );
};

export default HikingShopping;
